// ── GLOSSARY ──
const GLOSSARY = [
  {
    "term": "Indicator of malicious activity",
    "def": "An observable artifact — traffic rhythm, protocol quirk or host event — that suggests attacker activity."
  },
  {
    "term": "IoC vs IoA",
    "def": "IoC = a concrete artifact (domain, hash). IoA = the behavior being observed. Behaviors survive infrastructure changes better."
  },
  {
    "term": "Baseline",
    "def": "The measured \"normal\" for a network/host; anomalies are only meaningful relative to it."
  },
  {
    "term": "Beaconing",
    "def": "Regular-interval callbacks from a compromised host to attacker infrastructure (C2 heartbeat)."
  },
  {
    "term": "NetFlow",
    "def": "Summarized connection metadata (who↔who, ports, bytes, timing) — the workhorse for spotting traffic patterns."
  },
  {
    "term": "Packet capture",
    "def": "Full recorded network traffic for deep protocol inspection."
  },
  {
    "term": "DNS tunneling",
    "def": "Smuggling data through DNS queries, e.g. long encoded subdomains or TXT record bursts."
  },
  {
    "term": "SPF",
    "def": "Sender Policy Framework — DNS record listing servers allowed to send mail for a domain."
  },
  {
    "term": "DKIM",
    "def": "Cryptographic signature proving an email was not altered in transit."
  },
  {
    "term": "DMARC",
    "def": "Policy telling receivers what to do when SPF/DKIM fail (p=none means monitor only — no enforcement)."
  },
  {
    "term": "Header analysis",
    "def": "Reading full email headers (From, Return-Path, Reply-To, auth results) to expose spoofing."
  },
  {
    "term": "Encoded command",
    "def": "PowerShell -enc flag: base64-encoded script text — a hallmark of concealed execution."
  },
  {
    "term": "Parent–child anomaly",
    "def": "An unexpected process lineage, e.g. winword.exe spawning powershell.exe."
  },
  {
    "term": "Egress filtering",
    "def": "Controlling outbound traffic to known-good destinations so C2/exfil channels fail."
  },
  {
    "term": "False positive",
    "def": "An alert that fires on benign activity — the price of a detection that must be tuned against the baseline."
  },
  {
    "term": "Sinkholing",
    "def": "Redirecting malicious domains to a controlled address; also reveals every internal host that resolves them."
  }
];

